from taf.internal.protocol.tl1.command import ActUser, CancUser, OPRLinkFlap, EntCrsBulk


class TL1(object):
    def __init__(self, session):
        self._session = session

    def act_user(self, username, password, wait=1, recv_timeout=5, **kwargs):
        """
        Execute ACT-USER TL1 Message

        :param username: str, username e.g. admin
        :param password: str, password
        :param wait: int, time sleep after command sent, 1s by default
        :param recv_timeout: int, timeout when receive response message, 5s by default
        :param kwargs: ctag: int, non-zero decimal number,
                       tid: str, text string limited to 20 characters
        :return: Response object from .message module
        :exception: ReceiveOutputTimout, MessageFormatException
        """
        act_user_command = ActUser(self._session, uid=username, pid=password, **kwargs)
        return act_user_command.execute(wait=wait, recv_timeout=recv_timeout)

    def canc_user(self, exit_session=True, wait=1, recv_timeout=5, **kwargs):
        """
        Execute CANC-UESER TL1 Message.

        :param exit_session: bool, whether exit ssh session after execution, True by default.
        :param wait: int, time sleep after command sent, 1s by default
        :param recv_timeout: int, timeout when receive response message, 5s by default
        :param kwargs: ctag: int, non-zero decimal number,
                       tid: str, text string limited to 20 characters
                       uid: str, text string, the username what ACT-USER specified
        :return: Response object from .message module
        :exception: ReceiveOutputTimout, MessageFormatException
        """
        canc_user_command = CancUser(self._session, exit_session=exit_session, **kwargs)
        return canc_user_command.execute(wait=wait, recv_timeout=recv_timeout)

    def opr_link_flap(self, ports, wait=1, recv_timeout=5, **kwargs):
        """
        Execute OPR-LINK-FLAP TL1 Message.

        :param ports: str, port(s) No. format is up to the device. e.g. in calient 4.4.1 or 4.4.1&4.4.3
        :param wait: int, time sleep after command sent, 1s by default
        :param recv_timeout: int, timeout when receive response message, 5s by default
        :param kwargs: ctag: int, non-zero decimal number>,
                       tid: str, text string limited to 20 characters
                       uid: str, text string, the username what ACT-USER specified
                       lowperiod: UNION[str, int], 20ms-30min e.g. 20ms, unit is ms by default when entering int value
                       highperiod: UNION[str, int], 20ms-30min e.g. 40ms, unit is ms by default when entering int value
                       period: UNION[str, int], 40ms-1h e.g. 40ms, unit is ms by default when entering int value
                       frequency: UNION[float, str], 25Hz - 0.00027777Hz
                       repeat: int, 1-30
                       duration: UNION[str, int], 40ms-1h e.g. 40ms, unit is ms by default when entering int value
        :return: Response object from .message module
        :exception: ReceiveOutputTimout, MessageFormatException
        """
        opr_link_flap_command = OPRLinkFlap(self._session, ports=ports, **kwargs)
        return opr_link_flap_command.execute(wait=wait, recv_timeout=recv_timeout)

    def multiple_cross_connections(self, connection_list, wait=1, recv_timeout=5, **kwargs):
        """
        Execute ENT-CRS-BULK TL1 Message.
        This command allows the user to make multiple connections on an arbitrary batch of
        connections that have been entered and separated using the ampersand (&) character.

        :param connection_list: list, connections list can be uni-directional, bi-directional or a combination of both.
                                      Uni-directional connections are designated by entering the greater-than (>)
                                      character between the specified ports,
                                      while bi-directional connections are designated by entering the dash (–)
                                      character between the specified ports.
                                      e.g. ['4.3.1-5.1.1', '4.3.2>5.1.2']
        :param wait: int, time sleep after command sent, 1s by default
        :param recv_timeout: int, timeout when receive response message, 5s by default
        :param kwargs: tid: str, text string limited to 20 characters
        :return: Response object from .message module
        :exception: ReceiveOutputTimout, MessageFormatException
        """
        ent_crs_bulk_command = EntCrsBulk(self._session, conn_list=connection_list, **kwargs)
        return ent_crs_bulk_command.execute(wait=wait, recv_timeout=recv_timeout)
